//! Unit tests for the IQ4_XS CPU kernels.
//!
//! The expected values live in `testdata/iq4xs_oracle.bin`, generated by
//! `tools/iq4xs/oracle.cpp` linked against ggml itself (see
//! `tools/iq4xs/README.md`). That makes these tests a comparison against the
//! reference implementation rather than against a second port.

use super::*;
use candle_core::quantized::QTensor;

const BLOB: &[u8] = include_bytes!("../testdata/iq4xs_oracle.bin");

fn u32at(o: &[u8], i: usize) -> u32 {
    u32::from_le_bytes([o[i], o[i + 1], o[i + 2], o[i + 3]])
}

fn f32s(b: &[u8]) -> Vec<f32> {
    b.as_chunks::<4>()
        .0
        .iter()
        .map(|c| f32::from_le_bytes(*c))
        .collect()
}

struct Oracle {
    nb_real: usize,
    nb_syn: usize,
    nq: usize,
    real_raw: &'static [u8],
    real_deq: Vec<f32>,
    real_act: Vec<f32>,
    real_q8: &'static [u8],
    real_dot: Vec<f32>,
    syn_raw: &'static [u8],
    syn_deq: Vec<f32>,
    syn_act: Vec<f32>,
    syn_q8: &'static [u8],
    syn_dot: Vec<f32>,
    quant_in: Vec<f32>,
    quant_out: &'static [u8],
    quant_deq: Vec<f32>,
}

fn oracle() -> Oracle {
    assert_eq!(&BLOB[..8], b"IQ4XSOR1", "oracle blob magic");
    let nb_real = u32at(BLOB, 8) as usize;
    let nb_syn = u32at(BLOB, 12) as usize;
    let nq = u32at(BLOB, 16) as usize;
    assert!(nb_real > 0 && nb_syn > 0 && nq > 0);
    let mut o = 24usize;
    let real_raw = &BLOB[o..o + nb_real * BLOCK_BYTES];
    o += nb_real * BLOCK_BYTES;
    let real_deq = f32s(&BLOB[o..o + nb_real * QK_K * 4]);
    o += nb_real * QK_K * 4;
    let real_act = f32s(&BLOB[o..o + nb_real * QK_K * 4]);
    o += nb_real * QK_K * 4;
    let real_q8 = &BLOB[o..o + nb_real * Q8K_BYTES];
    o += nb_real * Q8K_BYTES;
    let real_dot = f32s(&BLOB[o..o + nb_real * 4]);
    o += nb_real * 4;
    let syn_raw = &BLOB[o..o + nb_syn * BLOCK_BYTES];
    o += nb_syn * BLOCK_BYTES;
    let syn_deq = f32s(&BLOB[o..o + nb_syn * QK_K * 4]);
    o += nb_syn * QK_K * 4;
    let syn_act = f32s(&BLOB[o..o + nb_syn * QK_K * 4]);
    o += nb_syn * QK_K * 4;
    let syn_q8 = &BLOB[o..o + nb_syn * Q8K_BYTES];
    o += nb_syn * Q8K_BYTES;
    let syn_dot = f32s(&BLOB[o..o + nb_syn * 4]);
    o += nb_syn * 4;
    let quant_in = f32s(&BLOB[o..o + nq * QK_K * 4]);
    o += nq * QK_K * 4;
    let quant_out = &BLOB[o..o + nq * BLOCK_BYTES];
    o += nq * BLOCK_BYTES;
    let quant_deq = f32s(&BLOB[o..o + nq * QK_K * 4]);
    o += nq * QK_K * 4;
    assert_eq!(o, BLOB.len(), "oracle blob has trailing bytes");
    Oracle {
        nb_real,
        nb_syn,
        nq,
        real_raw,
        real_deq,
        real_act,
        real_q8,
        real_dot,
        syn_raw,
        syn_deq,
        syn_act,
        syn_q8,
        syn_dot,
        quant_in,
        quant_out,
        quant_deq,
    }
}

fn close(a: f32, b: f32, tol: f32) -> bool {
    (a - b).abs() <= tol * b.abs().max(1.0)
}

fn assert_bits_eq(got: &[f32], want: &[f32], what: &str) {
    assert_eq!(got.len(), want.len(), "{what}: length");
    for (i, (g, w)) in got.iter().zip(want).enumerate() {
        assert_eq!(
            g.to_bits(),
            w.to_bits(),
            "{what}: block {} element {} got {g} want {w}",
            i / QK_K,
            i % QK_K
        );
    }
}

/// Whether the running CPU (on this arch) has AVX2.
#[cfg(target_arch = "x86_64")]
fn has_avx2() -> bool {
    is_x86_feature_detected!("avx2")
}
#[cfg(not(target_arch = "x86_64"))]
fn has_avx2() -> bool {
    false
}

/// AVX2 dequantize, or `false` when the CPU (or arch) does not have it.
#[cfg(target_arch = "x86_64")]
fn dequant_avx2_or_skip(raw: &[u8], out: &mut [f32]) -> bool {
    if !has_avx2() {
        return false;
    }
    // SAFETY: `has_avx2` just checked the feature.
    unsafe { dequantize_avx2(raw, out).unwrap() };
    true
}
#[cfg(not(target_arch = "x86_64"))]
fn dequant_avx2_or_skip(_raw: &[u8], _out: &mut [f32]) -> bool {
    false
}

/// AVX2 dot, or `None` when the CPU (or arch) does not have it.
#[cfg(target_arch = "x86_64")]
fn dot_avx2_or_skip(w: &[u8], q8: &[u8]) -> Option<f32> {
    if !has_avx2() {
        return None;
    }
    // SAFETY: `has_avx2` just checked the feature.
    Some(unsafe { vec_dot_q8_k_avx2(w, q8).unwrap() })
}
#[cfg(not(target_arch = "x86_64"))]
fn dot_avx2_or_skip(_w: &[u8], _q8: &[u8]) -> Option<f32> {
    None
}

fn skip_if_no_avx2() -> bool {
    if has_avx2() {
        return false;
    }
    eprintln!("skipping: no AVX2 on this CPU");
    true
}

/// Deterministic byte stream.
struct Rng(u32);
impl Rng {
    fn new(seed: u32) -> Self {
        Rng(seed)
    }
    fn next(&mut self) -> u32 {
        self.0 = self.0.wrapping_mul(1664525).wrapping_add(1013904223);
        self.0
    }
    fn f32(&mut self) -> f32 {
        // Uniform in [-1, 1).
        ((self.next() >> 8) as f32 / (1u32 << 24) as f32) * 2.0 - 1.0
    }
    fn bytes(&mut self, n: usize) -> Vec<u8> {
        (0..n).map(|_| (self.next() >> 24) as u8).collect()
    }
    /// Random packed blocks with a realistic finite `d` (the model's own `d` is
    /// around 1e-5), so comparisons stay well-conditioned.
    fn raw_blocks(&mut self, nb: usize) -> Vec<u8> {
        let mut raw = self.bytes(nb * BLOCK_BYTES);
        for b in 0..nb {
            let d = half::f16::from_f32(self.f32() * 1e-4).to_bits();
            raw[b * BLOCK_BYTES..b * BLOCK_BYTES + 2].copy_from_slice(&d.to_le_bytes());
        }
        raw
    }
    fn activations(&mut self, n: usize) -> Vec<f32> {
        (0..n).map(|_| self.f32()).collect()
    }
}

