/// The engine's decode path (`indexed_moe_fused_decode`: fused gate+up+act and
/// down+aggregate) must serve IQ4_XS as well.
#[cfg(feature = "cuda")]
#[test]
fn cuda_indexed_moe_fused_decode_matches_the_cpu_kernel() {
    use candle_core::cuda_backend::cudarc::driver::DevicePtr;
    use candle_core::{DType, Device, Storage, Tensor};

    const HIDDEN: usize = 256;
    const INTER: usize = 256;
    const E: usize = 4;
    const BATCH: usize = 3;
    const TOPK: usize = 2;

    fn pack(f: impl Fn(usize) -> f32, rows: usize) -> Vec<u8> {
        let mut out = vec![0u8; rows * BLOCK_BYTES];
        for r in 0..rows {
            let row: Vec<f32> = (0..QK_K).map(|i| f(r * QK_K + i)).collect();
            quantize_iq4_xs(&row, &mut out[r * BLOCK_BYTES..(r + 1) * BLOCK_BYTES]).unwrap();
        }
        out
    }

    // All-positive weights and activation: without cancellation the Q8_1 rounding
    // of the input and the intermediate activation stays a percent or so, so the
    // check is meaningful rather than dominated by a small residual.
    let gate = pack(|i| ((i as f32) * 0.13).sin().abs() * 0.4 + 0.1, E * INTER);
    let up = pack(|i| ((i as f32) * 0.17).cos().abs() * 0.4 + 0.1, E * INTER);
    let down = pack(|i| ((i as f32) * 0.19).sin().abs() * 0.4 + 0.1, E * HIDDEN);
    let x: Vec<f32> = (0..BATCH * HIDDEN)
        .map(|i| ((i as f32) * 0.11).cos().abs() + 0.5)
        .collect();
    let ids_data: [[u32; TOPK]; BATCH] = [[0, 2], [3, 1], [2, 2]];
    let weights: [[f32; TOPK]; BATCH] = [[0.6, 0.4], [0.5, 0.5], [0.3, 0.7]];

    // CPU reference: silu(gate x) * (up x), then down, weighted and summed.
    let mut want = vec![0f32; BATCH * HIDDEN];
    for t in 0..BATCH {
        let xt = &x[t * HIDDEN..(t + 1) * HIDDEN];
        for j in 0..TOPK {
            let ex = ids_data[t][j] as usize;
            let mut g = vec![0f32; INTER];
            gemv(
                &gate[ex * INTER * BLOCK_BYTES..(ex + 1) * INTER * BLOCK_BYTES],
                xt,
                &mut g,
            )
            .unwrap();
            let mut u = vec![0f32; INTER];
            gemv(
                &up[ex * INTER * BLOCK_BYTES..(ex + 1) * INTER * BLOCK_BYTES],
                xt,
                &mut u,
            )
            .unwrap();
            let act: Vec<f32> = g
                .iter()
                .zip(&u)
                .map(|(g, u)| (g / (1.0 + (-g).exp())) * u)
                .collect();
            let mut d = vec![0f32; HIDDEN];
            gemv(
                &down[ex * HIDDEN * BLOCK_BYTES..(ex + 1) * HIDDEN * BLOCK_BYTES],
                &act,
                &mut d,
            )
            .unwrap();
            let w = weights[t][j];
            for o in 0..HIDDEN {
                want[t * HIDDEN + o] += w * d[o];
            }
        }
    }

    let dev = Device::new_cuda(0).unwrap();
    let cuda = dev.as_cuda_device().unwrap();
    let gate_qt = crate::gguf::archive::qtensor_from_gguf_data(
        GgmlDType::IQ4XS,
        &gate,
        vec![E, INTER, HIDDEN],
        &dev,
    )
    .unwrap();
    let up_qt = crate::gguf::archive::qtensor_from_gguf_data(
        GgmlDType::IQ4XS,
        &up,
        vec![E, INTER, HIDDEN],
        &dev,
    )
    .unwrap();
    let down_qt = crate::gguf::archive::qtensor_from_gguf_data(
        GgmlDType::IQ4XS,
        &down,
        vec![E, HIDDEN, INTER],
        &dev,
    )
    .unwrap();
    let xs = Tensor::from_vec(x, (BATCH, HIDDEN), &dev).unwrap();
    let ids = Tensor::new(&ids_data, &dev)
        .unwrap()
        .flatten_all()
        .unwrap()
        .to_dtype(DType::U32)
        .unwrap();
    let (ids_storage, _ids_layout) = ids.storage_and_layout();
    let Storage::Cuda(ids_cuda) = &*ids_storage else {
        panic!("ids must be on CUDA");
    };
    let ids_slice = ids_cuda.as_cuda_slice::<u32>().unwrap();

    let wt = Tensor::new(&weights, &dev)
        .unwrap()
        .flatten_all()
        .unwrap()
        .to_dtype(DType::F32)
        .unwrap();
    let (wt_storage, _wt_layout) = wt.storage_and_layout();
    let Storage::Cuda(wt_cuda) = &*wt_storage else {
        panic!("weights must be on CUDA");
    };
    let wt_slice = wt_cuda.as_cuda_slice::<f32>().unwrap();
    let wt_ptr = wt_slice.device_ptr(wt_slice.stream()).0 as *const f32;

    // SAFETY: all tensors are contiguous, on this device, and `wt_ptr` points at
    // `BATCH * TOPK` f32 values.
    let got = unsafe {
        crate::gguf::cuda::indexed_moe_fused_decode(
            &gate_qt,
            &up_qt,
            &down_qt,
            &xs,
            ids_slice,
            wt_ptr,
            BATCH,
            TOPK,
            crate::gguf::cuda::ACT_SILU,
            cuda,
        )
    }
    .unwrap()
    .to_dtype(DType::F32)
    .unwrap()
    .flatten_all()
    .unwrap()
    .to_vec1::<f32>()
    .unwrap();
    assert_eq!(got.len(), BATCH * HIDDEN);
    // The CUDA path quantizes both the input and the intermediate activation to
    // Q8_1, so the tolerance is a few percent rather than a bit.
    let mut max_rel = 0f32;
    for (i, (g, w)) in got.iter().zip(&want).enumerate() {
        let rel = (g - w).abs() / w.abs().max(1.0);
        max_rel = max_rel.max(rel);
        assert!(rel <= 0.05, "fused decode element {i}: {g} vs {w}");
    }
    eprintln!("IQ4_XS fused decode max relative error: {max_rel:.4}");
}
